# The Hollow Parish - Act I overworld (location 101, OverworldLevel; docs/arch/10-m1-design.md 3.2)
#
# A fixed 32x32 macro grid; each macro cell is 4x4 tiles, so macro cell (cx,cy) covers tiles
# x 4cx..4cx+3, y 4cy..4cy+3. North is up. levels/world/OverworldLayout rasterises it: barriers
# (^ and ~), regions, the roads between road and road-node cells, spurs to the marker cells, stamps,
# lantern plots, transitions and the danger field. Markers and stamps below are in tile coordinates.
#
# Intended route: Coach Road -> Hagstone Moor -> Sallowmere (Flooded Cellars) -> back to the
# Crossways -> up the Lych Ridge to Lychgate Acre (Charnel House) -> north through Harrowdene -> west
# along the north shore -> Merrow Abbey (Abbey Crypts). Region adjacency (nearest region letter by a
# 4-way multi-source BFS over macro cells, ignoring ^ and ~, ties to the lower area-level band) is
# exactly c-m, m-s, m-l, l-h, h-a; m-l only through the road gap in the Lych Ridge at (24,20).
#
# Format: world/MapSource (section 3.4). Comments start with '#' at column 0; legend lines are indented.

kind overworld
size 128 128
scale 4
seed 0xD1AB011CA1                  # = Act1.LAYOUT_SEED (barrier edge jitter only)

legend
  ^ WALL                           # crags and dense wood (impassable)
  ~ CUSTOM_DECO_WTR                # Merrow Mere, deep water (impassable, see-through)
  w WATER                          # shallows and bog pools (passable)
  = road:lane                      # the Old Coach Road and its lanes
  c region:coach_road              # The Old Coach Road   AL 1-2
  m region:hagstone                # Hagstone Moor        AL 2-4
  s region:sallowmere              # Sallowmere           AL 4-6
  l region:lychgate                # Lychgate Acre        AL 6-8
  h region:harrowdene              # Harrowdene           AL 8-10
  a region:merrow                  # Merrow Abbey         AL 10-12
  1 road:node feature:lantern:act1.coach_road    # Coach Road Lantern
  2 road:node feature:lantern:act1.crossways     # Crossways Lantern
  3 road:node feature:lantern:act1.sallowmere    # Village Green Lantern
  4 road:node feature:lantern:act1.lychgate      # Lychgate Lantern
  5 road:node feature:lantern:act1.millrace      # Millrace Lantern
  6 road:node feature:lantern:act1.abbey_gate    # Abbey Gate Lantern
  + road:node feature:signpost     # the Crossways fingerpost
  I road:node feature:gate         # the gate to Lantern's Rest
  F feature:dungeon:cellars        # The Flooded Cellars, below the tithe barn
  C feature:dungeon:charnel        # The Charnel House, the parish bone-house
  K feature:dungeon:crypts         # The Abbey Crypts, below the south aisle
  x feature:sealed                 # sealed in M1 (Flooded Nave, Wolf-Holt, Hagstone Barrow)
  H feature:stamp:hagstone         # the Hagstone ring
  W feature:stamp:mail_coach       # the wrecked mail-coach
  V feature:stamp:cottage          # Sallowmere cottages
  G feature:stamp:church           # the church of Saint Ysolde and its graveyard
  M feature:stamp:mill             # the burnt mill
  A feature:stamp:abbey            # Merrow Abbey ruins
end

grid
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
^aaaaaaaa^^^^^^^^^^hhhhhhhhhhhh^
^axaaaaa==============hhhhhhhhh^
^aaaAaaa6aww~~~~wwhhh=hhhhhhxhh^
^aaaaAaa=w~~~~~~~~whh=hhhhhhhhh^
^aaKaaaaw~~~~~~~~~~wh=hhhhhhhhh^
^aaaaaaaw~~~~~~~~~~wh=hhhhhhhhh^
^aaaaaaaw~~~~~~~~~~wh=hMhhhhhhh^
^aaaaaaaw~~~~~~~~~~wh=5==hhhhhh^
^^^^^^^^^~~~~~~~~~~^hhhh=hhhhhh^
^ssssssssw~~~~~~~~w^hhhh=hhhhhh^
^ssssssss=ww~~~~wwm^hhhh=hhhhhh^
^ssssssss=sswwwwmmm^hhhh=hhhhhh^
^ssFsss===sssmmmmmm^llll=llllll^
^ssssss=sssssmmmmmm^llll=llllll^
^ssssVs=sssssmmmmmm^llll=lllCll^
^sssVss3sssssmmmmmm^lll4=lGllll^
^ssssVs=sssssmmmmmm^llll=llGlll^
^ssssss=ssssswmmmmm^llll=llllll^
^ssssss=sssswmmmmmm^llll=llllll^
^mmmmmm=mmmmmmmmmmm^^^^^=^^^^^^^
^mmmwmm========2+========^^^^^^^
^mmwmmmmmmmmmmmm=mmmmmmmmcccccc^
^mmmmmmmmmmmmmmm=mmmmmmmmcccccc^
^mmmxmmmcccccccc=cccccccccccccc^
^mmmmmmmHccccccc=cccccccccccccc^
^mmmmmmmcccwcccc=cccccccccccccc^
^mmmmmmmcccccccc1cWcccccccccccc^
^mmmmmmmcccccccc=cccccccccccccc^
^mmmmmmmcccccccc=cccccccccccccc^
^^^^^^^^ccccccccIcccccccc^^^^^^^
^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
end

# Special cells (tile coordinates). A lantern stands at (4cx+3, 4cy) of its digit's macro cell, never
# on the road band (4cx+1..4cx+2); a dungeon mouth or sealed entrance at (4cx+1, 4cy+1) of its cell.
markers
  gate 64 122 66 122               # I (16,30): EMPTY_SP gate cells, REGULAR_ENTRANCE -> 100
  gate_arrival 65 121              # arrivals from the town land here, one tile inside the gate
  debug_start 65 93                # road tile in Hagstone Moor, macro (16,23): ?start=act1 begins here
  lantern:act1.coach_road 67 108   # 1 (16,27)
  lantern:act1.crossways 63 84     # 2 (15,21)
  lantern:act1.sallowmere 31 64    # 3 (7,16)
  lantern:act1.lychgate 95 64      # 4 (23,16)
  lantern:act1.millrace 91 32      # 5 (22,8)
  lantern:act1.abbey_gate 35 12    # 6 (8,3)
  dungeon:cellars 13 53            # F (3,13): EXIT, REGULAR_EXIT -> 110
  dungeon:charnel 113 61           # C (28,15): EXIT, REGULAR_EXIT -> 120
  dungeon:crypts 13 21             # K (3,5): EXIT, REGULAR_EXIT -> 130
  sealed:nave 9 9                  # x (2,2): LOCKED_EXIT, text sealed_nave (the Flooded Nave)
  sealed:holt 113 13               # x (28,3): LOCKED_EXIT, text sealed_holt (the Wolf-Holt)
  sealed:barrow 17 97              # x (4,24): LOCKED_EXIT, text sealed_barrow (Hagstone Barrow)
  signpost 67 84                   # + (16,21): STATUE fingerpost, text signpost
end

# Stamp alphabet: S STATUE, X STATUE_SP, D DOOR, E EMBERS, T EMPTY_DECO, ',' GRASS, '.' EMPTY,
# '_' EMPTY_SP, '#' WALL, '~' WATER, '-' keep the tile.
stamps
  cottage                          # template: V cells and procedural cottages; the door faces the lane
  #####
  #___#
  #___#
  ##D##

  hagstone 30 98                   # the Hagstone ring; X is the holed stone
  ,,S,S,,
  ,S,,,S,
  S,,,,,S
  ,,,X,,,
  S,,,,,S
  ,S,,,S,
  ,,S,S,,

  mail_coach 72 108                # the wrecked mail-coach
  _XX_
  XXXE
  ,E,,

  church 104 64                    # T = pews; the graveyard rows continue in the fill
  ########
  #XTXTXT#
  #_T_T__#
  #XTXTXT#
  #______#
  #X____X#
  ###DD###
  -S,S,S,-

  mill 90 26                       # the burnt mill on the millrace
  #E##E#
  #EE_E~
  E__E_~
  #_E__~
  ##E#E~
  -----~

  abbey 14 10                      # Merrow Abbey ruins, 10x9 (the last row keeps the fill)
  ##-###-###
  #_______-#
  -_X___X__#
  #________-
  #_X___X__#
  ###___####
  -___~~~__-
  --__~~~---
  ----------
end
